(()=>{
const el=id=>document.getElementById(id),button=el('micToggle');
let audio=null,stream=null,source=null,analyser=null,capture=null,ring=null,head=0,filled=0,frame=0,generation=0,running=false,starting=false,spectrum=null,rate=48000;
function chart(id){const canvas=el(id),r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;const width=Math.max(300,r.width),height=r.height||250;if(canvas.width!==Math.round(width*d)||canvas.height!==Math.round(height*d)){canvas.width=Math.round(width*d);canvas.height=Math.round(height*d)}const c=canvas.getContext('2d');c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,width,height);c.font='10px system-ui';return {c,w:width,h:height,L:45,R:12,T:14,B:30};}
function axes(p,labels){const {c,w,h,L,R,T,B}=p;c.strokeStyle='#303945';c.fillStyle='#9da9b7';labels.forEach((label,i)=>{const y=T+(h-T-B)*i/(labels.length-1);c.beginPath();c.moveTo(L,y);c.lineTo(w-R,y);c.stroke();c.fillText(label,2,y+3)});}
function drawWave(){const p=chart('micWave'),{c,w,h,L,R,T,B}=p,n=Math.min(ring?.length||0,Math.round(rate*Number(el('micWindow').value)/1000));const read=i=>{const offset=n-i;return !ring||offset>filled?0:ring[(head-offset+ring.length)%ring.length]};let peak=0;for(let i=0;i<n;i++)peak=Math.max(peak,Math.abs(read(i)));const limit=el('micY').value==='auto'?Math.max(.005,peak*1.15):Number(el('micY').value);axes(p,[limit.toPrecision(2),'0',(-limit).toPrecision(2)]);const pw=w-L-R,ph=h-T-B;c.save();c.beginPath();c.rect(L,T,pw,ph);c.clip();c.strokeStyle='#b9ed81';c.lineWidth=1.2;c.beginPath();for(let x=0;x<Math.ceil(pw);x++){let lo=Infinity,hi=-Infinity;const begin=Math.floor(x/pw*n),end=Math.max(begin+1,Math.floor((x+1)/pw*n));for(let i=begin;i<Math.min(n,end);i++){const v=read(i);lo=Math.min(lo,v);hi=Math.max(hi,v)}if(!Number.isFinite(lo))lo=hi=0;const y=v=>T+ph/2-v/limit*ph/2;if(n>pw){c.moveTo(L+x,y(lo));c.lineTo(L+x,y(hi))}else{const v=read(Math.min(n-1,begin));if(x===0)c.moveTo(L+x,y(v));else c.lineTo(L+x,y(v))}}c.stroke();c.restore();c.fillStyle='#9da9b7';const duration=Number(el('micWindow').value);for(let i=0;i<=4;i++){const value=duration*(i/4-1);c.fillText((duration>=1000?(value/1000).toFixed(2)+' s':value.toFixed(0)+' ms'),L+pw*i/4-12,h-9)}}
function drawSpectrum(){const p=chart('micSpectrum'),{c,w,h,L,R,T,B}=p;axes(p,['−20','−60','−100']);const pw=w-L-R,ph=h-T-B,max=Math.min(20000,rate/2),log=el('micAxis').value==='log',freq=x=>log?20*Math.pow(max/20,x/pw):max*x/pw;const binHz=rate/8192;c.fillStyle='#7cbbef';for(let x=0;x<pw;x+=2){const a=Math.max(0,Math.floor(freq(x)/binHz)),b=Math.min((spectrum?.length||1)-1,Math.ceil(freq(x+2)/binHz));let db=-100;for(let i=a;i<=b;i++)db=Math.max(db,spectrum?.[i]??-100);const height=Math.max(0,Math.min(1,(db+100)/80))*ph;c.fillRect(L+x,T+ph-height,2,height)}c.fillStyle='#9da9b7';const labels=log?[20,100,1000,10000,max]:[0,max/4,max/2,3*max/4,max];for(const f of labels){const x=log?Math.log(f/20)/Math.log(max/20)*pw:f/max*pw;c.fillText(f>=1000?(f/1000).toFixed(0)+'k':f.toFixed(0),Math.min(w-30,L+x-6),h-9)}c.fillText('Hz',w-18,h-9);}
function draw(){drawWave();drawSpectrum()}
function tick(){if(!running)return;analyser.getFloatFrequencyData(spectrum);draw();frame=requestAnimationFrame(tick)}
function release(){running=false;cancelAnimationFrame(frame);if(capture){capture.port.onmessage=null;capture.disconnect()}source?.disconnect();analyser?.disconnect();stream?.getTracks().forEach(t=>t.stop());if(audio)audio.close().catch(()=>{});audio=stream=source=analyser=capture=null;button.textContent='🎙 Start microphone';button.setAttribute('aria-pressed','false');}
function stopMic(message=filled?'Microphone stopped. Last captured waveform and spectrum remain visible.':'Microphone off. Press Start to try again.'){generation++;starting=false;release();el('micStatus').textContent=message;}
async function startMic(){const request=++generation;starting=true;button.textContent='Cancel microphone request';el('micStatus').textContent='Waiting for microphone permission…';try{
  if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone access needs a supported browser on HTTPS or localhost.');
  const incoming=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});
  if(request!==generation){incoming.getTracks().forEach(t=>t.stop());return}stream=incoming;
  audio=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();if(request!==generation)return;
  rate=audio.sampleRate;ring=new Float32Array(Math.ceil(rate*5));head=filled=0;spectrum=new Float32Array(4096);spectrum.fill(-Infinity);
  const context=audio;await context.audioWorklet.addModule('mic-capture.js');if(request!==generation)return;
  source=context.createMediaStreamSource(stream);analyser=context.createAnalyser();analyser.fftSize=8192;analyser.minDecibels=-100;analyser.maxDecibels=-20;analyser.smoothingTimeConstant=.65;
  capture=new AudioWorkletNode(context,'mic-capture');capture.port.onmessage=event=>{if(!running)return;for(const v of event.data){ring[head]=v;head=(head+1)%ring.length;filled=Math.min(filled+1,ring.length)}};
  source.connect(analyser);analyser.connect(capture);capture.connect(context.destination);
  running=true;starting=false;button.textContent='■ Stop microphone';button.setAttribute('aria-pressed','true');
  el('micStatus').textContent='Microphone live · speak or hum to see the waveform and spectrum.';el('micInfo').textContent=`${(rate/1000).toFixed(1)} kHz sample rate · ${(rate/8192).toFixed(1)} Hz per FFT bin`;
  stream.getTracks().forEach(t=>t.onended=()=>{if(running)stopMic('Microphone disconnected. Reconnect it and press Start to try again.')});tick();
}catch(error){if(request!==generation)return;starting=false;release();const messages={NotAllowedError:'Microphone permission was denied. Allow microphone access in your browser’s site settings, then try again.',NotFoundError:'No microphone was found. Connect one and try again.',NotReadableError:'The microphone could not be opened. Check whether another app is using it.'};el('micStatus').textContent=messages[error.name]||error.message||'Microphone could not start. Please try again.';}}
button.onclick=()=>running||starting?stopMic():startMic();['micWindow','micY','micAxis'].forEach(id=>el(id).onchange=draw);new ResizeObserver(draw).observe(el('micWave'));document.addEventListener('visibilitychange',()=>{if(document.hidden&&(running||starting))stopMic('Microphone stopped because this page is no longer visible. Press Start to resume.')});window.addEventListener('pagehide',()=>stopMic());draw();
})();
